    \end{enumerate}
\end{thm}

ref_dict.seq_ent_blowup:
\begin{thm} \label{seq_ent_blowup}
    Given any sequence of non-negative integers $A$ that dilates to infinity, there is a rank one system $(X,\cB,\mu,T)$ such that $h^A(T) = +\infty$.
\end{thm}

ref_dict.zero_seq_ent:
\begin{thm} \label{zero_seq_ent}
Let $(X,\mathcal{B},\mu,T)$ be a rank one system of finite measure approximated by a sequence of towers $S_n$ with base $F_n$ and height $h_n$.
\begin{enumerate}[label=(\roman*)]
    \item \label{zero_seq_ent.1} Let $A=\{t_n\}$ be a subexponential sequence. If \[\varlimsup_{n \to \infty}\frac{\log h_{n+1}}{\log h_{n}} < \infty,\] then $h^A(T)=0$.
    \item \label{zero_seq_ent.2} Let $A=\{t_n\}$ where $t_n = O(n^\alpha)$ for some $\alpha>1$. If there exists $\beta \in (0,\frac{1}{\alpha-1})$ such that \[\varlimsup_{n \to \infty}\frac{\log h_{n+1}}{h_{n}^{\beta}}<\infty,\] then $h^A(T) = 0$.
    \item \label{zero_seq_ent.3} Let $A=\{t_n\}$ where $t_n = \lfloor Cn(\log n)^\alpha\rfloor$ for some $C,\alpha>0$. If there exists $\beta \in (0,\frac{1}{\alpha})$ such that \[\varlimsup_{n \to \infty}\frac{\log h_{n+1}}{e^{h_{n}^{\beta}}}<\infty,\] then $h^A(T) = 0$.
\end{enumerate}
\end{thm}

post_theorem_intro_text:
\begin{rem}
    We would like to acknowledge that Dou and Park have also independently established an affirmative answer to \cite{Kanigowski24}*{Question 6.4.3} in their forthcoming work, utilising deterministic walks in random scenes.
\end{rem}

Theorem~\ref{seq_ent_blowup} may be generalised slightly to accommodate sequences which contain a large subsequence that dilates to infinity. More specifically, let $J = \{n_k\} \subseteq \mathbb{N}$ be a strictly increasing sequence. We say that the sequence $A=\{t_n\}$ \emph{dilates to infinity on $J$} if the subsequence $A_J=\{t_{n_k}\}$ dilates to infinity. By a large subsequence $J \subseteq \mathbb{N}$ we mean a subsequence of positive lower density $\underline{d}(J)$.

\begin{cor} \label{seq_ent_blowup.2}
Let $A$ be a sequence of positive integers that dilates to infinity on a subsequence of positive lower density, then there exists a rank one system $(X,\mathcal{B},\mu,T)$ such that $h^A(T)=+\infty$.
\end{cor}

In \cite{Krug72}, a formula for sequence entropy is given by $h^A(T) = K(A) \cdot h(T)$ where
\[K(A) = \lim_{r \to \infty} \varlimsup_{n \to \infty} \frac{1}{n}\#\set{t_i+j}{1 \le i \le n, -r \le j \le r}\]
detects the size of gaps between successive terms in $A = \{t_n\}$ as $n$ tends to infinity. In cases where $K(A)<+\infty$ such as in linear sequences $A=\{an+b\}$, this forces $h^A(T)=0$ for all zero entropy systems. In light of Corollary \ref{seq_ent_blowup.2} one may ask the following:

\begin{qn} \label{qn:Krug-Newton}
    Is the condition $K(A) = +\infty$ equivalent to $A$ dilating to infinity on a subsequence of positive lower density? If not, for a sequence $A$ that does not satisfy the latter, does there exist a measure-preserving system $(X,\mathcal{B},\mu,T)$ such that $h^A(T)>0$?
\end{qn}

\medskip

On the other hand, we will show that for subexponential but superlinear sequences, there is a lowest threshold for the rate of growth of heights between each subsequent tower in a rank one system, below which necessarily gives rise to zero sequence entropy.

\begin{thm} \label{zero_seq_ent}
Let $(X,\mathcal{B},\mu,T)$ be a rank one system of finite measure approximated by a sequence of towers $S_n$ with base $F_n$ and height $h_n$.
\begin{enumerate}[label=(\roman*)]
    \item \label{zero_seq_ent.1} Let $A=\{t_n\}$ be a subexponential sequence. If \[\varlimsup_{n \to \infty}\frac{\log h_{n+1}}{\log h_{n}} < \infty,\] then $h^A(T)=0$.
    \item \label{zero_seq_ent.2} Let $A=\{t_n\}$ where $t_n = O(n^\alpha)$ for some $\alpha>1$. If there exists $\beta \in (0,\frac{1}{\alpha-1})$ such that \[\varlimsup_{n \to \infty}\frac{\log h_{n+1}}{h_{n}^{\beta}}<\infty,\] then $h^A(T) = 0$.
    \item \label{zero_seq_ent.3} Let $A=\{t_n\}$ where $t_n = \lfloor Cn(\log n)^\alpha\rfloor$ for some $C,\alpha>0$. If there exists $\beta \in (0,\frac{1}{\alpha})$ such that \[\varlimsup_{n \to \infty}\frac{\log h_{n+1}}{e^{h_{n}^{\beta}}}<\infty,\] then $h^A(T) = 0$.
\end{enumerate}
\end{thm}

Theorem~\ref{zero_seq_ent} relies on upper bounds from a combinatorial counting of all possible orbits with respect to a carefully chosen sequence of optimal towers based on orbit length. The bounds for $\alpha$ in \ref{zero_seq_ent.2} and \ref{zero_seq_ent.3} are sharp, as formulated in Theorem~\ref{pos_seq_ent} below.

\begin{thm} \label{pos_seq_ent}
    There is a rank one system $(X,\mathcal{B},\mu,T)$ with sequence of tower heights $h_n$ such that $h^A(T)>0$, in addition to either one of the following constraints:
    \begin{enumerate}[label=(\roman*)]
        \item \label{pos_seq_ent.1}  For some $\alpha, \beta > 0$ where $\alpha \ge 1+1/\beta$, $A=\lfloor n^\alpha \rfloor$ and
        \[\varlimsup_{n \to \infty}\frac{\log h_{n+1}}{h_{n}^{\beta}}<\infty;\]
        \item \label{pos_seq_ent.2} For some $\alpha,\beta > 0$ where $\alpha \ge 1/\beta$, $A=\lfloor n(\log n)^\alpha \rfloor$ and
        \[\varlimsup_{n \to \infty}\frac{\log h_{n+1}}{e^{h_{n}^{\beta}}}<\infty.\]
    \end{enumerate}
\end{thm}

Finally, we provide a partial resolution to Question~\ref{qn:seq_ent_flex} for polynomial sequences of the form $t_n=\lfloor n^\alpha \rfloor$:

\begin{thm} \label{weak_flex_seq_ent}
    Let $\beta > 0$ and $t_n=\lfloor n^\alpha \rfloor$ where $\alpha = 1+1/\beta$.
    \begin{enumerate}[label=(\roman*)]
        \item \label{small_flex} For any $m > 0$, there is a rank one system $(X,\mathcal{B},\mu,T)$ such that $0<h^A(T)<m$;
        \item \label{large_flex} For any integer $L \ge 2$, there is a rank one system $(X,\mathcal{B},\mu,T)$ such that \[C_1 \log L \le h^A(T) \le C_2 \log L,\]
        where $C_1=\frac{\beta}{1+\beta}, C_2=(2\beta)^{\frac{1}{1+\beta}}$ depends only on $\beta$.
    \end{enumerate}
\end{thm}

Note that we have $C_1 < C_2$ for any given $\beta \in (0,+\infty)$. Part~\ref{large_flex} implies that for large values of $M>0$, there exists zero entropy systems that achieve a sequence entropy of $M$ up to a multiplicative factor of around $\sqrt{C_2/C_1}$, which has an upper bound of $\sqrt{3}$ when $\beta=0.5$ and converges to 1 as $\beta \to \infty$. This may serve as heuristic evidence for the full flexibility result of sequence entropy along superlinear sequences, at least for sequences with some regularity.

\subsection*{Structure of the paper:} In Section \ref{sec:definitions} we provide a few definitions and fix some notations. In Section \ref{sec:lower_bounds_prob} and \ref{sec:generic_stacks} we lay the groundwork for Section \ref{sec:seq_ent_blowup} where we prove the blow-up result of sequence entropy by randomizing the cut-and-stack procedure of a rank one system. Section \ref{sec:zero_seq_ent} investigates when sequence entropy necessarily vanishes, and Section~\ref{sec:weak_seq_ent_flex} establishes the partial result on the flexibility of sequence entropy along polynomial sequences.

\subsection*{Acknowledgement} This work is supported by the Singapore International Graduate Award (SINGA) Scholarship from the National University of Singapore funded by the Ministry of Education. The author would like to thank Daren Wei for fruitful discussions and his warm encouragement throughout the writing of this paper.

