ref_dict.horizontalnon:
\begin{theorem}\label{horizontalnon}
There does not exist any $C^1$ smooth surface of degree $2$ in the Engel group.
\end{theorem}

ref_dict.genres:
\begin{theorem}[Upper blow-up]\label{genres}
Let $\Sigma \subset \mathbb{G}$ be a smooth $k$-dimensional submanifold of class $C^1$ and 
degree $\NN$. Let $p \in \Sigma$ be a point of maximum degree $\NN$. 
 For the translated submanifold
$
\Sigma_p = p^{-1}\Sigma,
$
we introduce the $C^1$ smooth homeomorphism $\eta : \R^k \rightarrow \R^k$ by
\begin{equation}\label{funzioneeta}
\eta(t) = \Big(\frac{\lvert t_1 \rvert^{b_1}}{b_1}{\rm sgn}(t_1), \ldots, \frac{\lvert t_p \rvert^{b_k}}{b_k}{\rm sgn}(t_k)\Big)
\end{equation}
where $b_i$ is the induced degree, defined as follows
\begin{equation}\label{inducedb}
    b_i = j \quad \mbox{if and only if } \mu_{j - 1} < i \leq \mu_j
\end{equation}
for every $i=1 \ldots,k$,
where $\mu_j$ are defined in \eqref{def:mu_j}.
If $\phi$ denotes the mapping of Theorem~\ref{t:specialcoord}
applied to 
$\Sigma_p$, we define the $C^1$ smooth mapping
\begin{equation}\label{funzionegamma}
  \Gamma = \phi \circ \eta  
\end{equation}
and we set the subset of indexes $I \subset \{1,\ldots, n\}$ such that
\begin{equation*}
        A_0 \Sigma = { \rm span} \{ 
        e_1, \ldots, e_{\alpha_1}, e_{m_1 + 1}, \ldots, e_{m_1 + \alpha_2}, \ldots, e_{m_{\iota- 1} + 1}, \ldots, e_{m_{\iota -1} + \alpha_\iota}
        \}.
\end{equation*} 
Using notation and definitions of \cite[Theorem~3.1]{Magnani2019Area}, 
	if we assume the validity of the local expansion   
	\begin{equation}\label{localexp}
		\Gamma_s(t) = 
		\begin{cases}
			\frac{\lvert t_{s - m_{d_s - 1} + \mu_{d_s - 1}}\rvert^{d_s}}{d_s} {\rm sgn}(t_{s - m_{d_s - 1} + \mu_{d_s - 1}}) \;\; \mbox{if } s \in I \\
			o(\lvert t \rvert^{d_s}) \quad \quad \mbox{if } s \not \in I
		\end{cases},
	\end{equation}
	and $\beta_d \big(A_p \Sigma \big)$ denotes the \emph{spherical factor} associated to the homogeneous tangent space $A_p \Sigma$ in \eqref{sfe}, then
	\begin{equation}\label{eq:betadens}
	\theta^N(\mu_\Sigma, p) = \beta_d \big(A_p \Sigma \big).
	\end{equation}
\end{theorem}

