\begin{Thm}\label{theo-1.1}
		Let $\mathcal{G}$ be a periodic quantum graph as above with fundamental cell $\mathcal{K}$, and assume that $(\omega)$, $(V_{1})$ and $(F_{0})$--$(F_{5})$ hold. Then the NLDE \eqref{eq-1.5} admits at least one bound state $u$. If, in addition to the above assumptions, $F$ is even in $u$, then the NLDE \eqref{eq-1.5} possesses infinitely many geometrically distinct bound states.
	\end{Thm}

ref_dict.theo-1.2:
\begin{Thm}\label{theo-1.2}
		Let $\mathcal{G}$ be a periodic quantum graph as above with fundamental cell $\mathcal{K}$, and assume that $(\omega)$, $(V_{1})$ and $(F_{0})$--$(F_{2})$, $(F_{5})$, $(F_{6})$, $(F_{7})$ hold. Then the NLDE \eqref{eq-1.5} admits at least one bound state $u$. If, in addition to the above assumptions, $F$ is even in $u$, then the NLDE \eqref{eq-1.5} possesses infinitely many geometrically distinct bound states.
	\end{Thm}

