ref_dict.conj:GEM:
\begin{conjecture}[Generalised Euclid--Mullin conjecture]
\label{conj:GEM}
Let $a,m\in\N$ with $a^2\equiv1\pmod{m}$. Then
\begin{itemize}
\item[(i)] there exists $f\in\GEM(a,m)$ such that $\GEM_1(f;a,m)$ contains
every prime $p\equiv a\pmod{m}$;
\item[(ii)] for any $f\in\GEM(a,m)$, $\GEM_2(f;a,m)$ omits infinitely many
primes $p\equiv a\pmod{m}$.
\end{itemize}
\end{conjecture}

ref_dict.thm:firstprime:
\begin{theorem}\label{thm:firstprime}
Let $m>2$ be a power of $2$, and let $c\in S(m)$.
Then $\GEM_2(\Phi_m(cx);1,m)$ omits the smallest prime $p\equiv1\pmod{m}$
if $(m,c)\notin\{(4,\pm2),(4,\pm3),(8,\pm2)\}$,
and the second smallest such prime otherwise.
\end{theorem}

ref_dict.thm:unconditional:
\begin{theorem}\label{thm:unconditional}
Let $m\in\{1,\ldots,10,12,14,18\}$ and $c\in S(m)$,
with the following further assumptions:
\begin{align*}
m=1&\implies c\in\N\cup(2\Z\setminus32\Z)\cup\{-5\}\cup\bigl\{1-2^k:k\in\N\bigr\},\\
m=2&\implies c\in-\N\cup(2\Z\setminus32\Z).
\end{align*}
Then $\GEM_2(\Phi_m(cx);1,m)$ omits infinitely many primes $p\equiv1\pmod{m}$.
\end{theorem}

ref_dict.thm:orderl:
\begin{theorem}\label{thm:orderl}
Let $\ell$ be an odd prime number, let $q_1,\ldots,q_r$ be distinct
primes different from $\ell$, and let $\epsilon_1,\ldots,\epsilon_r\in\C^\times$ be arbitrary $\ell$th roots of unity. Then, assuming ERH,
there exists a primitive character $\chi$ of squarefree conductor $d$
with the following properties:
\begin{itemize}
\item $\chi$ has order dividing $\ell$;
\item every prime $p\mid d$ satisfies $p\ll\ell^4\log^2(\ell q_1\cdots q_r)$;
\item $\chi(q_j)=\epsilon_j$ for $j=1,\ldots,r$.
\end{itemize}
\end{theorem}

ref_dict.thm:ERH:
\begin{theorem}\label{thm:ERH}
Let $m\in\N$ and $c\in S(m)$. Then, assuming ERH,
$\GEM_2(\Phi_m(cx);1,m)$ omits infinitely many primes $p\equiv1\pmod{m}$.
\end{theorem}

