theorem.content:
\label{thm:main}
Let Assumption~\ref{assumption:standing} hold with
\begin{equation*}
p\leq \frac{c}{\log(mn)}
\quad\text{and}\quad
r\leq \min\left\{c\sqrt{\frac{\min\{m, n\}}{\mu \log^2(mn)}},\,k\right\},
\end{equation*}
where $c>0$ is a sufficiently small universal constant.
Then there exists a universal constant $C>0$ such that, with probability at least $1-\exp\{-Cr\log^2(mn)\}$, any $(X^{\star},Y^{\star})\in \mathcal L$ is a
(Clarke) critical point of $f$.
Moreover, it is a local minimum when $k = r$, and a strict saddle point\footnote{We say that a point is a strict saddle point if it is a critical point that violates the second-order necessary condition for optimality \cite[Theorem~13.24]{rockafellar2009variational}.}
when $k>r$.

ref_dict.eq:obj:
\begin{equation}
\label{eq:obj}
\min_{X \in \mathbb{R}^{m \times k},\, Y \in \mathbb{R}^{n \times k}}
f(X,Y) := \left\| X Y^\top - M \right\|_{1}.
\end{equation}

ref_dict.assumption:standing:
\begin{assumption}
\label{assumption:standing}
The observed matrix $M \in \mathbb{R}^{m \times n}$ is the sum of a low-rank matrix $L$ and a sparse matrix $S$, i.e., $M = L + S$, where:
\begin{enumerate}
    \item \textbf{Low-rank structure and incoherence:} The matrix $L$ has rank $r$ and is $\mu$-incoherent: let $L = U \Sigma V^\top$ be its singular value decomposition, then
    \begin{equation}
    \label{eq:incoh}
    \max_i \|U_i\|_2 \leq \sqrt{\frac{\mu r}{m}}
    \quad\text{and}\quad
    \max_j \|V_j\|_2 \leq \sqrt{\frac{\mu r}{n}},
    \end{equation}
    where $U_i$ and $V_j$ denote the $i$-th and $j$-th rows of $U$ and $V$, respectively.

    \item \textbf{Sparse corruption model:} The entries of $S$ are independent, and each entry is nonzero with probability $p > 0$.
\end{enumerate}
\end{assumption}

ref_dict.thm:main:
\begin{theorem}
\label{thm:main}
Let Assumption~\ref{assumption:standing} hold with
