ref_dict.thm:IntroMain:
\begin{theorem}\label{thm:IntroMain}
        Fix an $n\times n$ matrix $A$ with entries in an algebraically closed field of characteristic $0$ or $>n$. There exists a nonzero diagonal matrix $D$ such that $A$ and $A+D$ have the same spectrum if and only if for some $k$, the $k \times k$ principal minors of $A$ are not all equal.
    \end{theorem}

ref_dict.cor: adjacency matrix:
\begin{corollary}\label{cor: adjacency matrix}
    Suppose that $A$ is the adjacency matrix of a weighted simple graph $G$. There exists a nonzero diagonal matrix $D$ such that $A$ and $A+D$ have the same spectrum if $G$ is neither edgeless nor complete with all edge weights equal up to sign. 
\end{corollary}

ref_dict.Cor:FloquetMain:
\begin{theorem} \label{Cor:FloquetMain} 
    Let $\Lambda=q_1\mathbb{Z}\oplus q_2 \mathbb{Z}\oplus\cdots\oplus q_d\mathbb{Z}$  with $q_j\in\ZZ_{>0}$. If at least one of the periods $q_j$ is greater than $3$, then there exists a nonzero $\Lambda$–periodic complex potential $V$ Floquet isospectral to $\mathbf{0}$. If all $q_j\leq 3$ and at most two of the $q_j$ are equal to $3$, then the only $\Lambda$–periodic potential Floquet isospectral to $\mathbf{0}$ is $V\equiv \mathbf{0}$.
\end{theorem}

ref_dict.thm:mainembeddingprt:
\begin{thm}
\label{thm:mainembeddingprt}
Let $k$ be a local field. Let $\mathbf G$ be a simply
connected $k$-isotropic almost $k$-simple linear algebraic $k$-group such that $\rk_k(\mathbf G) \geq 2$ and set $G = \mathbf G(k)$. Let $\mathbf P < \mathbf G$ be a minimal parabolic $k$-subgroup and set $P = \mathbf P(k)$. Let $\Gamma<G$ be a lattice and $(\cN,\tau)$ be a trace-preserving ergodic $G$-von Neumann algebra such that $Z(\Gamma)$ acts trivially on $\cN$. Let $\Lambda=\Gamma/Z(\Gamma)$ and $\Phi:=\mathbb{E}_{\tau}\circ\mathbb{E}: (L^\infty(G/P,\nu_P) \overline{\otimes} \mathcal{N}) \rtimes\Lambda \to L^\infty(G/P,\nu_P)$ be the canonical conditional expectation. Then for any $\Gamma$-invariant von Neumann algebra
$ \mathcal{M} \subset (L^\infty(G/P,\nu_P) \overline{\otimes} \mathcal{N}) \rtimes\Lambda
$, the following dichotomy holds:
\begin{itemize}
\item Either $\Phi$ is $\Gamma$-invariant, that is, $\Phi(\cM)=\mathbb{C}1$.
\item Or there exist a proper parabolic $k$-subgroup $\mathbf P < \mathbf Q < \mathbf G$ and a $\Gamma$-equivariant unital normal embedding $\iota : L^\infty(G/Q) \hookrightarrow \cM$ where $Q = \mathbf Q(k)$ such that $\mathbb{E} \circ \iota : L^\infty(G/Q) \hookrightarrow L^\infty(G/P)$ is the canonical unital normal embedding. In particular, $L^\infty(G/Q)\subset \cM\cap L^\infty(G/P)$.
\end{itemize}
\end{thm}

ref_dict.thm:mainsplitting:
\begin{thm}
\label{thm:mainsplitting}
Let $G$ and $P$ be as above. Let $\Gamma<G$ be an irreducible lattice with finite center and set $\Lambda=\Gamma/Z(\Gamma)$. Let $(\cN,\tau)$ be a trace-preserving $G$-von Neumann algebra, on which each $G_i$ acts ergodically and $Z(\Gamma)$ acts trivially. Then every von Neumann algebra $\mathcal{M}$ with
\[
\mathcal{N} \rtimes\Lambda\subset \mathcal{M} \subset (L^\infty(G/P, \nu_P) \overline{\otimes} \mathcal{N}) \rtimes \Lambda
\]
is a crossed product of the form $(L^\infty(G/Q, \nu_Q) \overline{\otimes} \mathcal{N}) \rtimes \Lambda$ for some $P<Q<G$. 
\end{thm}

post_theorem_intro_text:
The above theorem provides new examples of a non-commutative analogue of the intermediate factor theorem
for product lattices, extending the rigidity result obtained in
Boutonnet-Houdayer~\cite{boutonnet2023noncommutative} to the tensor-product setting. 

The proof relies on four main ingredients and essentially follows the same strategy employed in \cite{boutonnet2023noncommutative}.
First, for $d\geq 2$, we make essential use of the notion of $G_i$–continuous elements,
introduced and studied in \cite{bader2022charmenability} and further dealt with in \cite{boutonnet2023noncommutative}. Roughly speaking, we show that $G_i$-continuous elements remain invariant under tensoring by the tracial von Neumann algebra $({\mathcal N},\tau)$. 
\begin{thm}
\label{thm:invarince undertensor}
Following the notations as in Theorem \ref{thm:mainsplitting}, assume that $d\geq 2$. Then for each $1 \le i \le d$, the von Neumann subalgebra $\mathcal{M}_i$ of $G_i$–continuous elements in $\left(L^\infty(G/P, \nu_{P})\overline{\otimes} \mathcal{N}\right) \rtimes \Lambda$
is $L^\infty(G_i/P_i, \nu_{P_i})$.
\end{thm}
Second, for $d=1$, we need a version of the non-commutative Nevo-Zimmer theorem established in \cite{boutonnet2021stationary,bader2023charmenability} for a $k$-simple connected algebraic $k$-group with $\rk_k(\mathbf G) \geq 2$, which is a direct corollary of \cite[Theorem 5.4]{bader2023charmenability} (see Theorem~\ref{thm:mainembeddingprt}).

Thirdly, we pair the analytic techniques of
Suzuki~\cite{suzuki}
along with the structural arguments of Bader–Boutonnet–Houdayer–Peterson~\cite {bader2022charmenability} to achieve the desired crossed-product rigidity.  As mentioned earlier, we follow the strategy used by Boutonnet-Houdayer~\cite{boutonnet2023noncommutative}, and adapt it to our purpose of providing ${\mathcal M}=\cM_0\rtimes \Lambda$. 

Finally, the classification of the intermediate von Neumann algebra $\mathcal{M}$ now reduces to understanding the structure of the $\Gamma$-invariant coefficient subalgebra $\mathcal{M}_0$. Using the non-commutative versions of Bader-Shalom \cite{amrutam2025non} and Stuck-Nevo-Zimmer (see Theorem~\ref{thm:nciftfield}), we show that every such intermediate algebra $\cM_0$ is a tensor product. Actually, we have the following more general result without any assumption on the center of lattice.
\begin{thm}
\label{thm:tensorproducts}    
Let $G$ and $P$ be as above. Let $\Gamma<G$ be an irreducible lattice. Let $({\mathcal N},\tau)$ be a trace-preserving $G$-von Neumann algebra such that each $G_i$ acts ergodically on ${\mathcal N}$. Then, any $\Gamma$-invariant intermediate von Neumann algebra 
$$\mathcal{N}\subset \mathcal{M}_0 \subset L^\infty(G/P, \nu_P) \overline{\otimes} \mathcal{N}$$
is actually a $G$-invariant subalgebra of the form $\mathcal{M}_0=L^\infty(G/Q, \nu_Q) \overline{\otimes} \mathcal{N}$ for some $P<Q<G$.
\end{thm}

\subsection*{Convenience} 
Throughout this paper, we assume that all von Neumann algebras have separable preduals.

ref_dict.def:quasitoral:
\begin{defn}[Quasitoral nilspaces]\label{def:quasitoral}
We say that a $k$-step \textsc{cfr} nilspace $\ns$ is \emph{quasitoral} if for every $i\in [2,k]$ the structure group $\ab_i(\ns)$ is a torus.
\end{defn}

ref_dict.ex:nonext:
\begin{example}[A non-extendable polynomial map]\label{ex:nonext}
Fix any prime $p$ and let $\ab=\mb{Z}_{p^2}\times \mb{Z}_p$ and $\ab_0=(p\mb{Z}_{p^2})\times \mb{Z}_p\leq \ab$. Consider the morphism $g\in \hom(\mc{D}_1(\ab_0),\mc{D}_2(\mb{T}))$ defined by $g(px,y)=\frac{xy}{p}$, where the point $\frac{xy}{p}\in \mb{T}$ is obtained by taking any integer representatives of $x$ (mod $p^2$) and $y$ (mod $p$) and then taking $\frac{xy}{p}\mod 1$ (note that this is well-defined and indeed a quadratic map, i.e.\ a morphism into $\mc{D}_2(\mb{T})$ as claimed). We claim that there is no morphism $\wt{g}:\mc{D}_1(\ab)\to\mc{D}_2(\mb{T})$ such that $\wt{g}|_{\ab_0}=g$. Indeed, suppose for a contradiction that such a map $\wt{g}$ exists. Then, composing it with the natural surjective homomorphism $\mb{Z}^2\to \ab$ (i.e.\ reduction mod $p^2$ in the first coordinate and mod $p$ in the second), we obtain a morphism $h:\mc{D}_1(\mb{Z}^2)\to \mc{D}_2(\mb{T})$ which is $p^2$-periodic in the first coordinate, and $p$-periodic in the second coordinate. Moreover, from the assumption that $\wt{g}(px,y)=g(px,y)=\frac{xy}{p}\mod 1$, we deduce that for all integers $x,y$ we have $h(px,y)= \frac{xy}{p}$. We thus have the following system of constraints:
\begin{align}
 \forall x,y\in \mb{Z},  & \quad h(x+p^2,y)=h(x,y) \label{eq:circ1} \\ 
 \forall x,y\in \mb{Z}, & \quad h(x,y+p)=h(x,y) \label{eq:circ2} \\
 \forall x,y\in \mb{Z}, & \quad h(px,y)=\frac{xy}{p}.\label{eq:circ3}
\end{align}
On the other hand, since $h$ is a quadratic map into $\mb{T}$, it has a Taylor expansion of the form $h(x,y)=a_1+a_2x+a_3y+a_4\binom{x}{2}+a_5\binom{y}{2}+a_6xy$ for some $a_i\in \mb{T}$. Now note that from equation \eqref{eq:circ3} evaluated successively at $(x,y)=(0,0),(0,1),(0,2)$, we deduce that $a_1=0$, then $a_3=0$, and then $a_5=0$. Hence  $h(x,y)=a_2x+a_4\binom{x}{2}+a_6xy$. Now, applying this in \eqref{eq:circ2} we deduce that $a_6xp=h(x,y+p)-h(x,y)=0$ for all $x$, whence $a_6p=0$. Then, using this back in \eqref{eq:circ3} we obtain that $a_2px+a_4\binom{px}{2}=\frac{xy}{p}$, which, setting $x=1$, gives us the absurd claim that the constant $a_2p+a_4\binom{p}{2}$ equals $\frac{y}{p}$ for all $y$. This proves that the extension $\wt{g}$ cannot exist.\footnote{Note that we did not use equation \eqref{eq:circ1} to derive the contradiction, only \eqref{eq:circ2} and \eqref{eq:circ3}. This is not concerning because it can be checked that equation \eqref{eq:circ1} is actually redundant; more precisely, this equation can be deduced from equation \eqref{eq:circ3} by evaluating the latter further at $(1,0)$ and $(2,0)$ and deducing from this that $a_2$, $a_4$ and $a_6$ must be such that $h$ is forced to be $p^2$-periodic in $x$.}
\end{example}

ref_dict.thm:bndrankinv-intro:
\begin{theorem}\label{thm:bndrankinv-intro}
For any $k,R\in \mb{N}$ and $\delta>0$, there is $\varepsilon>0$ and a finite collection $\mc{N}_{k,R,\delta}$ of degree-$k$ filtered nilmanifolds $G/\Gamma$, each equipped with a smooth Riemannian metric and with connected and simply-connected ambient group $G$, such that the following holds. For any  finite abelian group $\ab$ of rank at most $R$, and any 1-bounded function $f:\ab\to\mb{C}$ with $\|f\|_{U^{k+1}}\geq \delta$, there exists $G/\Gamma\in \mc{N}_{k,R,\delta}$, a Lipschitz 1-bounded function $F:G/\Gamma\to\mb{C}$ of Lipschitz norm $O_{k,R,\delta}(1)$, and a polynomial map $g:\ab\to G/\Gamma$, such that $|\mb{E}_{x\in \ab} f(x)\overline{F(g(x))}| \geq \varepsilon$.
\end{theorem}

expanded_sketch:
Our proof of the main theorem can be divided into two main steps.

(1) Apply the inverse theorem \cite[Theorem 5.2]{CSinverse} and show that, in the bounded-rank setting, the resulting nilspace is a \emph{quasitoral} nilspace (i.e. for every $i\in[2,k]$ the structure group $\ab_i(\mathrm{X})$ is a torus). Then show that quasitoral nilspaces are disjoint unions of toral nilspaces (connected nilmanifolds). For the quasitoral nilspace $\mathrm{X}$ obtained from \cite[Theorem 5.2]{CSinverse}, the number of toral-nilspace components depends only on the complexity of $\mathrm{X}$ and hence is bounded. Consequently, on some bounded-index subgroup $\mathrm{Z}'\leq \mathrm{Z}$, some shift of $f$ correlates non-trivially with a bounded-complexity nilsequence on $\mathrm{Z}'$.

(2) Prove that the nilsequence on $\mathrm{Z}'$ can be extended to a nilsequence on the full group $\mathrm{Z}$ while keeping bounded complexity. To solve this extension problem in general, it is necessary to modify the nilmanifold underlying the nilsequence; this necessity is illustrated by the following example.

\begin{example}[A non-extendable polynomial map]\label{ex:nonext}
Fix any prime $p$ and let $\ab=\mb{Z}_{p^2}\times \mb{Z}_p$ and $\ab_0=(p\mb{Z}_{p^2})\times \mb{Z}_p\leq \ab$. Consider the morphism $g\in \hom(\mc{D}_1(\ab_0),\mc{D}_2(\mb{T}))$ defined by $g(px,y)=\frac{xy}{p}$, where the point $\frac{xy}{p}\in \mb{T}$ is obtained by taking any integer representatives of $x$ (mod $p^2$) and $y$ (mod $p$) and then taking $\frac{xy}{p}\mod 1$ (note that this is well-defined and indeed a quadratic map, i.e.\ a morphism into $\mc{D}_2(\mb{T})$ as claimed). We claim that there is no morphism $\wt{g}:\mc{D}_1(\ab)\to\mc{D}_2(\mb{T})$ such that $\wt{g}|_{\ab_0}=g$. Indeed, suppose for a contradiction that such a map $\wt{g}$ exists. Then, composing it with the natural surjective homomorphism $\mb{Z}^2\to \ab$ (i.e.\ reduction mod $p^2$ in the first coordinate and mod $p$ in the second), we obtain a morphism $h:\mc{D}_1(\mb{Z}^2)\to \mc{D}_2(\mb{T})$ which is $p^2$-periodic in the first coordinate, and $p$-periodic in the second coordinate. Moreover, from the assumption that $\wt{g}(px,y)=g(px,y)=\frac{xy}{p}\mod 1$, we deduce that for all integers $x,y$ we have $h(px,y)= \frac{xy}{p}$. We thus have the following system of constraints:
\begin{align}
 \forall x,y\in \mb{Z},  & \quad h(x+p^2,y)=h(x,y) \label{eq:circ1} \\ 
 \forall x,y\in \mb{Z}, & \quad h(x,y+p)=h(x,y) \label{eq:circ2} \\
 \forall x,y\in \mb{Z}, & \quad h(px,y)=\frac{xy}{p}.\label{eq:circ3}
\end{align}
On the other hand, since $h$ is a quadratic map into $\mb{T}$, it has a Taylor expansion of the form $h(x,y)=a_1+a_2x+a_3y+a_4\binom{x}{2}+a_5\binom{y}{2}+a_6xy$ for some $a_i\in \mb{T}$. Now note that from equation \eqref{eq:circ3} evaluated successively at $(x,y)=(0,0),(0,1),(0,2)$, we deduce that $a_1=0$, then $a_3=0$, and then $a_5=0$. Hence  $h(x,y)=a_2x+a_4\binom{x}{2}+a_6xy$. Now, applying this in \eqref{eq:circ2} we deduce that $a_6xp=h(x,y+p)-h(x,y)=0$ for all $x$, whence $a_6p=0$. Then, using this back in \eqref{eq:circ3} we obtain that $a_2px+a_4\binom{px}{2}=\frac{xy}{p}$, which, setting $x=1$, gives us the absurd claim that the constant $a_2p+a_4\binom{p}{2}$ equals $\frac{y}{p}$ for all $y$. This proves that the extension $\wt{g}$ cannot exist.\footnote{Note that we did not use equation \eqref{eq:circ1} to derive the contradiction, only \eqref{eq:circ2} and \eqref{eq:circ3}. This is not concerning because it can be checked that equation \eqref{eq:circ1} is actually redundant; more precisely, this equation can be deduced from equation \eqref{eq:circ3} by evaluating the latter further at $(1,0)$ and $(2,0)$ and deducing from this that $a_2$, $a_4$ and $a_6$ must be such that $h$ is forced to be $p^2$-periodic in $x$.}
\end{example}

