\begin{theorem}\label{Teo2}
\begin{enumerate}
\item[i)] {($\Gamma$-$\liminf$ inequality)}

Let \( \{( \boldsymbol{u}^{(j)}, \alpha^{(j)})\}_{j \in \mathbb{N}} \) be a sequence 
in~\( \mathcal{A} \). 
Assume that for some $\left( \widehat{\vec u}, \widehat{\alpha} \right) \in \mathcal{A}$,
the sequence $\Big ( \overline{u}_3^{(j)} \Big )_{j\in\N}$ defined by \eqref{eq:horizontal_averages_u3}
converges weakly in $L^2(\Omega)$ to $\widehat{u}_3$, and that $\alpha^{(j)}$ converges strongly in $L^2(\Omega)$ to $\widehat{\alpha}$.
Then 
\begin{align*}
	 E_\infty[\widehat {\vec u}, \widehat \alpha]
	 \leq \liminf_{j\to\infty} E_j[\vec u^{(j)}, \alpha^{(j)}].
\end{align*}

\item[ii)] {(\, $\Gamma$-$\limsup$ inequality)}

Given any $(\vec u,\alpha)\in \mathcal{S}$, it is possible to construct a sequence $(\boldsymbol{u}^{(j)},\alpha^{(j)})$ in $\mathcal{A}$ such that
 $$ \big (u_3^{(j)}, \alpha^{(j)}\big) \quad \text{converges strongly in } L^{2}(\Omega)\times L^2(\Omega)
 \text{ to } \big (u_3, \alpha\big ), $$
    and
    \[
    \lim_{j \to \infty} E_j[{\vec u}^{(j)}, \alpha^{(j)}] =\int_0^1 a_\eta\big(\alpha(z)\big) \cdot  \frac{1}{2} E u_3'(z)^2 + w\big(\alpha(z)\big) + \frac{w_1 \ell^2}{2L^2} |\alpha'(z)|^2  \, \mathrm{d}z.
    \]
\end{enumerate}
\end{theorem}

